'use client'

import { toggleNotificationPreference } from './actions'

interface NotificationToggleProps {
  userId: string
  initialPreference: boolean
}

export function NotificationToggle({ userId, initialPreference }: NotificationToggleProps) {
  const handleToggle = async () => {
    await toggleNotificationPreference(userId)
  }

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
      <h2>Notification Settings</h2>
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginTop: '10px' }}>
        <span>Notifications:</span>
        <strong>{initialPreference ? 'ON' : 'OFF'}</strong>
      </div>
      <button
        onClick={handleToggle}
        style={{
          marginTop: '15px',
          padding: '10px 20px',
          backgroundColor: initialPreference ? '#dc3545' : '#28a745',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer',
        }}
      >
        Turn {initialPreference ? 'Off' : 'On'}
      </button>
      <p style={{ marginTop: '10px', fontSize: '14px', color: '#666' }}>
        Click the button to toggle. The page will refresh to show the updated preference.
      </p>
    </div>
  )
}

